{
 "kind": "sequence",
 "format": 1,
 "id": "seq_deadball_close",
 "name": "Deadball: postgame",
 "set": "set_ksab5_desk",
 "roles": {
  "a": {
   "mark": "a",
   "label": "Lead anchor"
  },
  "b": {
   "mark": "b",
   "label": "Analyst"
  }
 },
 "wallText": "Final",
 "wallSub": "KSAB5 Sports",
 "beats": [
  {
   "id": "b3",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "drift",
    "cut": "dissolve"
   },
   "say": {
    "role": "a",
    "lines": [
     "That's the ballgame. {winner} over {loser}. {away} {awayScore}, {home} {homeScore}.",
     "Final from {venue}. {winner} win it, {away} {awayScore}, {home} {homeScore}."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ],
   "wall": "brand"
  },
  {
   "id": "b1",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "{innings} innings to settle it. Both bullpens are spent."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "extras",
     "op": "=",
     "value": "true"
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "b"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "A shutout for {winner}. {loser} never got a man home."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "shutout",
     "op": "=",
     "value": "true"
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "{winner} got the hits when they needed them. {hits} between the two clubs.",
     "{loser} left too many men on. You can't do that and win."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "Stars of the game",
     "list": "stars",
     "row": "{n}. {name}: {tonight}",
     "limit": 6,
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam2",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "{gameStar.name} takes it tonight. {gameStar.tonight}."
    ]
   },
   "gfx": [
    {
     "kind": "profile",
     "who": "gameStar",
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "gameStar",
     "op": "has"
    }
   ]
  },
  {
   "id": "b6",
   "shot": {
    "cam": "jib",
    "frame": "full",
    "on": [
     "a",
     "b"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "That's it from the desk. For {b.name}, I'm {a.name}. Thanks for watching.",
     "Next game's coming up on KSAB5. I'm {a.name}, good night."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{a.name} and {b.name}",
     "sub": "KSAB5 Sports",
     "at": 0.4,
     "for": 5
    }
   ],
   "wall": "list",
   "wallList": "table",
   "wallRow": "{n}. {team}: {wins}-{losses}",
   "wallText": "Standings"
  }
 ]
}
